Link::Link(PMat* start, PMat* end, glm::vec3 force)
    : startParticle(start), endParticle(end), forceValue(force) {}

void Link::applyGravity() {
    if (!startParticle || !endParticle) {
        std::cerr << "Error: Link contains null particles!" << std::endl;
        return;
    }

    PMat* P = startParticle;

    while (P && P != endParticle) {  // Ensure P is valid
        P->applyForce(forceValue);
        P++;  // ⚠️ This assumes a contiguous memory layout, which is incorrect.
    }

    endParticle->applyForce(forceValue);  // Ensure last particle gets the force
}

